def solve(rows):
    kept_rows = []
    state = 3
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 13 != 3 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 3
        else:
            state = (3 * state + weight) % 13

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_kept_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    grouped_data = {}
    for row in rotated_kept_rows:
        if len(row) == 4 and isinstance(row, list):
            group, score, timestamp, name = row
            if group not in grouped_data:
                grouped_data[group] = []
            grouped_data[group].append((score, timestamp, name))

    result = []
    for group in sorted(grouped_data.keys()):
        data = grouped_data[group]
        best_row = max(data, key=lambda x: (x[0], -x[1], x[2]))
        result.append([group, best_row[2]])

    return result

